   "summary": "統計推論是用「有限的樣本」去推測「整個母體」，並量化不確定性，主要分兩支。參數估計回答「這個數字大概是多少」：給出點估計（例如平均體重 68 公斤）與信賴區間（例如 95% CI 為 [66, 70]）。假設檢定回答「某個主張成不成立」：先設定虛無假設 H0（例如新藥沒效），再看樣本資料是否足以推翻它，輸出檢定統計量與 p 值，並依顯著水準 α 決定是否拒絕 H0。流程為：設定虛無／對立假設、選檢定方法與統計量、決定 α、計算統計量與 p 值、比較 α 並下決策。機器學習中常用來判斷特徵是否與目標顯著相關、兩個模型的差異是否真有統計意義。",
