   "summary": "資料常有數十到數百個特徵，但並非每個都有貢獻；全部丟進模型會增加運算成本，也容易過擬合。維度簡化（降維）就是利用矩陣分解等技術，把資料壓縮成少數有代表性的特徵組合，保留主要變異、排除雜訊與重複資訊。主成分分析（PCA）是最常用的方法：找出一組能最大化資料變異量的正交方向（主成分），再把資料投影過去，同時達成降維與特徵重組。實作上可對協方差矩陣做特徵值分解，或對資料做 SVD。好處包括：提升訓練效率、去除雜訊與共線性而更穩定、轉換後的特徵較容易解釋、降到 2～3 維後便於視覺化。",
