   "summary": "當梯度變得異常大（梯度爆炸），一次更新就可能把權重推得很遠，造成損失劇烈震盪、發散，甚至出現 NaN 或數值溢位，RNN 與深層網路特別常見。梯度裁剪（Gradient Clipping）就是替梯度設一個上限：若梯度（的範數）超過門檻，就把它按比例縮小或截斷，讓每一步更新的幅度受控。它是處理「梯度爆炸」的優先技術。在 PyTorch 訓練迴圈中的順序是：zero_grad、前向計算輸出、計算 loss、loss.backward() 產生梯度、梯度裁剪（如 clip_grad_norm_）、optimizer.step() 更新權重；也就是要放在 backward 之後、step 之前。",
