   "summary": "當特徵很多、彼此又高度相關時，普通線性迴歸的係數容易忽大忽小。Lasso 與嶺迴歸的做法，是在損失函數後面加一項「懲罰」，逼係數不要太大。Lasso 加的是 L1 項（係數絕對值總和 λΣ|β|），特性是能把部分係數直接壓到 0，等於自動做特徵選擇；嶺迴歸（Ridge）加的是 L2 項（係數平方和 λΣβ²），只把係數縮小、不會變成 0，特別適合多重共線性嚴重的情況。λ 是正則化強度，太小沒效果、太大會壓過頭而欠擬合，需靠交叉驗證選。兩者仍假設線性關係，無法建模非線性。",
