   "guidePages": "4-17～4-19",
   "summary": "支援向量迴歸（SVR）是支援向量機（SVM）的迴歸版本。普通線性迴歸在意每個點的平方誤差，SVR 卻先劃出一條寬度為 ε 的「容忍帶」（ε-tube）：預測誤差落在帶子內就當作沒誤差、不計較，只有掉到帶子外的點才會被懲罰，所以比較不受離群值干擾。目標函數 ½‖w‖² + CΣ(ξ + ξ*)，前半讓模型保持簡單平滑，後半（C 是懲罰參數）處罰超出容忍範圍的誤差。配合核函數（如 RBF）就能擬合非線性關係。缺點是計算量大、參數（C、ε、核函數與 γ）難調、不易解釋，訓練時間與記憶體隨樣本數平方增長，不適合極大資料。",
   "keyPoints": [
    "SVM 的迴歸延伸；找超平面使預測誤差落在 ε 容忍範圍（ε-tube）內，只處罰超出範圍的點",
    "C（懲罰參數）控制模型複雜度與對誤差的容忍度；ε 決定容忍帶寬度",
    "搭配核函數可做非線性迴歸；不需誤差常態假設，對異常值較有抵抗力",
    "限制：計算成本高、參數設定複雜（C、ε、核函數與 γ）、非線性核時不易解釋、不適合極大規模資料"
   ],
   "trap": "SVM 用於迴歸時叫 SVR（Support Vector Regression），不是 Logistic Regression；SVR 忽略 ε 範圍內的誤差，並非最小化所有點的平方誤差。",
