   "summary": "一棵決策樹很容易過擬合，那就種一整片森林：隨機森林（Random Forest）建立很多棵樹，每棵樹都用不同的隨機子樣本（Bootstrap 抽樣）訓練，而且每次分裂節點時只隨機挑部分特徵來考慮，讓每棵樹各有「個性」。預測時，迴歸取所有樹預測值的平均，分類則由所有樹多數決投票。因為各棵樹彼此獨立，可以平行訓練；還能算出特徵重要性協助特徵篩選。它屬於 Bagging 路線，主要降低變異（Variance）。缺點是整體像黑箱、難解釋，模型體積大、吃記憶體，預測也比單棵樹慢；遇到極端不平衡資料仍可能偏向多數類別。",
