   "summary": "LightGBM 是和 XGBoost 並列的高效梯度提升實作，最大差異在「樹怎麼長」。XGBoost 採層級式（Level-wise）：一層一層橫向長，同一深度的葉子一起分裂；LightGBM 採葉子式（Leaf-wise）：每次只挑「分裂後增益（gain）最大」的那片葉子來分裂，樹往縱深長，形成較深但不一定均勻的結構。這樣用更少的計算就能更快降低損失，對大數據、大特徵數尤其有效；再搭配直方圖演算法（Histogram-based）降低計算複雜度，記憶體也更省。代價是：小型資料集上，葉子式容易長出不平衡的深樹而過擬合，必須用 max_depth 等參數設限，否則還可能耗盡記憶體。",
