   "summary": "樸素貝氏（Naïve Bayes）是用貝氏定理做分類的機率模型：P(C|X) = P(X|C) × P(C) / P(X)，也就是「看到這些特徵後，樣本屬於類別 C 的後驗機率」，最後把樣本分到機率最高的類別。為了讓計算可行，它做了一個「樸素」的簡化——假設給定類別時各特徵彼此條件獨立，於是 P(X|C) 可拆成各特徵機率的連乘。現實中特徵很少真的獨立，但它在文本分類、垃圾郵件過濾、情感分析上仍表現穩健，訓練快、預測快，適合大規模資料與即時預測。限制：強獨立假設、「零機率」問題（某特徵值在該類別從未出現，整個後驗會變 0，要用拉普拉斯平滑）、對輸入分佈假設敏感，且不能直接做迴歸。",
