   "summary": "K-means 是最經典的分群演算法：你先決定要分成 K 群，它就把每個點分到離自己最近的「質心」所在的群。流程：①隨機挑 K 個點當初始質心；②把每個點分配給最近的質心；③把每群所有點的平均值重新當成新質心；④重複②③，直到質心幾乎不再移動或達到最大迭代次數。優點是簡單、快、處理大量資料效率高。缺點也很明確：必須事先指定 K；結果對初始質心敏感（所以每次跑可能略有不同）；對離群值敏感（極端點會拉歪平均）；只能形成球形或凸形群集，遇到月牙形等不規則形狀就失靈。",
