   "summary": "階層式分群（Hierarchical Clustering）不先決定要分幾群，而是建出一整棵樹狀圖（Dendrogram），讓你看到資料在不同層次的聚合狀況，再決定在哪一層「切一刀」得到分群結果。有兩種方向：凝聚式（Agglomerative）由下而上，一開始每個點自成一群，每一步把最相似的兩群合併，直到只剩一個大群；分裂式（Divisive）由上而下，從所有點同屬一群開始，每步把一個群拆成更小的子群，直到每個點各成一群。優點是不用預設 K、樹狀圖利於理解層次結構；缺點是計算量大、資料多時效率低、對離群值敏感，而且合併或分裂一旦做了就不能撤銷，可能得到次優解。",
