   "summary": "DBSCAN 是基於密度的分群：想像人潮聚集的地方就是一個群，稀稀落落走散的人就是雜訊。它有兩個關鍵參數：Eps（鄰域半徑，每個點周圍的搜尋範圍）和 MinPts（形成核心群集所需的最小點數）。若某點的 Eps 鄰域內點數 ≥ MinPts，它就是核心點，從核心點出發會把所有「密度可達」的點（含其他核心點與邊界點）併入同一群；鄰域點數不足的點，若落在某核心點的鄰域內就是邊界點，否則就是噪聲點。優點：不需預先指定群數、能找出任意形狀的群集、能自動標出離群值；缺點：對 Eps、MinPts 高度敏感、處理密度不均的群集效果差、高維資料的距離與密度難以定義。",
