   "guidePages": "4-48～4-49",
   "summary": "購物籃分析的經典問題是：哪些商品常被一起買？關聯規則學習就是從大量交易中找出這種共現規律。Apriori 先找出「頻繁項目集」（出現比例達最小支持度的商品組合），再從中生成達到最小信賴度的規則 A⇒B。關鍵是 Apriori 性質：頻繁項集的所有子集必定也頻繁；反過來，不頻繁的項集，包含它的任何超集一定也不頻繁，因此可提前剪枝。三個標準：支持度＝同時含 A 和 B 的交易佔總交易的比例；信賴度＝在含 A 的交易中也含 B 的條件機率 P(B|A)；提升度 Lift ＝信賴度 ÷ P(B)，>1 正相關、<1 負相關、=1 獨立。缺點是要多次掃描、產生大量候選集，高維稀疏資料上很慢。",
