   "summary": "Apriori 的痛點是要產生大量候選項集並反覆掃描資料。FP-Growth 換了個思路：把整個交易資料壓縮成一棵緊湊的 FP 樹（Frequent Pattern Tree），再直接從樹裡挖出頻繁項目集，完全不需要產生候選集。步驟：第一次掃描統計各項目支持度；移除低於最小支持度的項目，把剩下的頻繁項依支持度由高到低排序；第二次掃描，把每筆交易變成樹上的一條路徑，節點是頻繁項、計數是該路徑出現的次數；最後遞歸構建條件模式基與條件 FP 樹，抽取所有頻繁項集。所以只需掃描兩次資料，通常比 Apriori 快很多。缺點：超大且複雜的資料建樹可能吃很多記憶體；極度稀疏時樹壓縮不了多少，優勢減弱。",
