   "guidePages": "4-71～4-72",
   "summary": "CNN 從 2012 年起快速演進，每個經典模型都為解決某個痛點而生。AlexNet 奪下 2012 年 ImageNet 大賽（ILSVRC）冠軍，用深層架構、ReLU、Dropout 與 GPU 加速，掀起深度學習熱潮。VGG 以多個 3×3 小卷積核堆疊取代大卷積核，網路深而結構簡單。GoogLeNet 的 Inception 模塊並行使用不同大小的卷積核與池化再拼接，捕捉多尺度特徵。ResNet 用殘差連接解決超深網路的梯度消失。DenseNet 讓每層連接前面所有層，重用特徵。MobileNet、EfficientNet 追求輕量高效，適合手機等資源受限環境。",
