   "summary": "自編碼器（Autoencoder）是一種非監督式學習模型，玩的是「壓縮再還原」的遊戲：編碼器把高維的輸入壓縮成低維的潛在向量（中間最窄的地方叫瓶頸層），解碼器再把它還原成原本的維度。訓練目標是最小化重構誤差，也就是讓還原出來的資料與原始輸入越像越好，連續資料常用均方誤差（MSE），二元資料用二元交叉熵。為了在狹窄的瓶頸中還原資料，模型被迫丟掉冗餘資訊、只保留最重要的特徵。用途有降維與壓縮、特徵學習、去噪（去噪自編碼器），以及異常偵測：模型只熟悉正常資料，重構異常資料時誤差會變大。缺點是它主要用來重構，不像 GAN 能生成全新多樣的樣本。",
