   "summary": "特徵工程不是亂套工具，而是靠對資料與任務的理解，把原始欄位變成「對模型更有用的輸入」。常見的思路有四條：一、依任務設計——分類偏好能分群的離散特徵（類別指標、區間），迴歸偏好與數值趨勢相關的連續特徵；二、依模型調整——線性模型要注意尺度與共線性，KNN 等距離式模型要確保單位一致；三、挖掘隱含結構——欄位合成（單價×數量＝總價）、兩個特徵相乘或交叉組合做成「互動特徵」，統計聚合（過去 7 天的點擊次數）；四、時間序列——做滯後值（lag）、移動平均（rolling mean），或用滑動窗口把過去多個時間點的觀測組成模型輸入。",
