   "summary": "邏輯迴歸、SVM、神經網路等多數演算法看不懂文字類別，要先編碼成數字。Label Encoding 把每個類別對應成一個整數（小學 0、高中 1、大學 2），適合「本來就有順序」的類別；若拿來編無序類別（城市名），模型會誤以為 2 比 0 大。One-hot Encoding 為每個類別開一個 0／1 欄位（紅／藍／綠變成三欄），不引入順序，適合無序類別，但類別一多（高基數，例如 3,000 種商品）欄位數暴增，吃記憶體、拖慢訓練。Target Encoding 用各類別在目標變數上的平均（如各廣告來源的轉換率）取代類別，不增加維度，適合高基數且與目標高度相關的特徵，但要小心資料洩漏。",
