   "guidePages": "5-24",
   "summary": "殘差＝實際值－預測值。畫殘差圖（橫軸預測值、縱軸殘差）是檢查迴歸模型品質的好辦法。理想狀況是殘差隨機散落在 0 附近、上下寬度差不多，看不出任何規律。如果呈現系統性彎曲（U 形或波浪），代表模型漏掉了非線性關係；少數點殘差特別大，可能是異常值；殘差隨預測值增大而擴散成喇叭形，代表殘差變異數不一致（異質變異性），違反迴歸的等變異假設；殘差依序有規律、相鄰殘差彼此相關，則是自相關，常見於時間序列。看到這些訊號，可考慮加入非線性項、對目標或特徵做轉換（如取 Log）、處理異常值，或改用更合適的模型。（指引對殘差圖著墨很少，本卡依迴歸診斷的通則整理。）",
