   "guidePages": "5-45～5-46",
   "summary": "過擬合的症狀是「訓練集表現很好、驗證或測試集變差」（例如訓練 F1=0.96、驗證 0.71）。對策可分三類：一、限制模型複雜度——L1／L2 正則化、減少層數與神經元、降低特徵數；二、改變訓練方式——Dropout（訓練時隨機關閉部分神經元，預測時不丟棄）、Early Stopping（監控驗證集損失，連續 patience 次沒進步就停止）；三、讓資料更豐富——取得更多資料、資料增強。增加特徵、加大模型、訓練更久這類反向做法只會加重過擬合。調校時：Dropout 機率太高會學不起來；patience 太短會欠擬合，太長仍可能過擬合；早停要看驗證集，不能看訓練集或測試集。",
