   "guidePages": "5-19、5-31～5-32",
   "summary": "學習率（learning rate）決定每次更新參數「走多大一步」，是訓練者事先指定的超參數，不是模型自己學出來的。太大：步伐過大，在最低點兩側反覆跳越，損失震盪甚至發散，也可能出現梯度爆炸（NaN）；太小：走得太慢、訓練效率差，也可能卡在局部極小值或鞍點。理想是前期大一點快速下降、後期調小精細收斂，所以常搭配調度器：遞減（Step、Exponential Decay）、驗證表現停滯就降低（ReduceLROnPlateau）、預熱（warm-up，從小慢慢升高，常見於 Transformer）。若收斂時快時慢，首先要調的就是學習率；批次大小與學習率高度耦合，改了批次大小，學習率也要重調。",
   "keyPoints": [
    "學習率是人設定的超參數，控制每次更新的幅度，是訓練中最敏感的設定之一。",
    "太大→損失震盪或發散、可能梯度爆炸；太小→收斂慢、可能卡在局部極小或鞍點。",
    "常見調度策略：固定、遞減（Step／Exponential Decay）、ReduceLROnPlateau、warm-up。",
    "批次大小改變後，學習率通常也要重新調整。"
   ],
   "trap": "問「學習率過大最直接導致什麼」→ 震盪或發散；梯度消失（與深度、激活函數有關）、過擬合、死亡 ReLU 都不是最直接的現象。",
