     "explanation": "答案 C。學習率是超參數，控制模型權重更新的速度，調整它能改善收斂不穩定。A 錯：神經元輸出是計算結果；B 錯：梯度變化值是由損失與資料算出來的，不是人設定；D 錯：權重是訓練學出來的，不是超參數。",
