   "summary": "知識蒸餾：讓大而準的「教師模型」教較小的「學生模型」，學生用教師輸出的軟標籤（機率分佈）學習，在體積小、速度快的前提下逼近教師的表現。適合部署到手機或邊緣裝置，也能降低即時應用的延遲；缺點是要額外訓練時間與運算資源，教師若有偏誤也會傳給學生。剪枝（Pruning）：移除對結果影響小的權重或神經元。結構化剪枝移除整個神經元、卷積通道或層，容易與硬體加速器整合；非結構化剪枝移除零散的單一權重，模型變稀疏，但多數硬體對稀疏矩陣支援差，實際加速有限。剪太多會讓準確率明顯下降。蒸餾、剪枝與量化可以搭配使用。",
