   "summary": "批次大小（batch size）是每次更新參數時，用幾筆樣本來計算梯度。小批次：梯度帶比較多雜訊、路徑搖晃，這份隨機性有時有助於跳出局部極小值，但太小會讓訓練震盪、迭代次數與時間增加。大批次：梯度估計穩定、硬體利用率高，單輪訓練更快，但可能降低泛化能力、收斂變慢或卡在較差的局部最小，而且受限於 GPU 記憶體，超過上限會直接訓練失敗。更重要的是批次大小與學習率高度耦合：批次放大卻沒有重調學習率，訓練可能無效或不穩。深度學習最常用 mini-batch SGD；傳統機器學習大多是全量訓練，沒有這個設定。（三種梯度下降的運作機制見 3.3「小批次梯度下降」，本卡著重調校。）",
