   "summary": "K-匿名、L-多樣性、T-接近性是針對結構化表格的進階匿名化指標，一個比一個嚴。K-匿名：在準識別欄位（年齡、性別…）上，每筆紀錄至少與其他 K−1 筆相同，所以你混在至少 K 個人裡，無法被單獨鎖定。但若這 K 個人的疾病全都一樣，攻擊者仍能推測，所以有 L-多樣性：每個群組內敏感欄位（如疾病）至少有 L 種不同的值。若值雖多樣但分佈很偏，也會洩漏，T-接近性則要求群組內敏感欄位的分佈與全體資料相近。限制：計算複雜、K 太大會損失精度，對文字、影像等非結構化資料適用性有限。",
