   "guidePages": "6-11～6-13",
   "summary": "AI 訓練不只是技術問題，還要合法合規。合法來源與告知同意：同意必須自由（不可被迫）、明確具體（載明項目、目的、範圍、保存期間，不可用籠統條款）、可撤回；沒有同意則要有其他法定依據，如履行契約、法定義務、正當利益。資料最小化與目的限制：只蒐集必要的最低限度資料，不得挪作未告知的用途，敏感資料更要審慎。去識別化：對外共享前優先匿名化並做再識別測試，保留風險評估紀錄。透明與紀錄：記錄來源、法律基礎、處理流程、保護措施，並定期稽核。跨境傳輸：如 GDPR 規定歐盟居民個資移出歐盟，需有足夠保護措施或標準合約條款。",
