   "summary": "指引把資料偏見依「出在哪個環節」分成三類。來源偏誤（Source Bias）出在蒐集階段：資料沒有均衡涵蓋該代表的群體或情境，例如醫療資料缺某年齡層或性別、資料集中在都市與高收入者、語料只來自北美、資料只來自特定社群平台。內容偏誤（Content Bias）出在資料內容本身：資料帶有刻板印象或歷史不平等，例如把「醫師」預設為男性，或信用審核歷史資料隱含種族、性別歧視，模型會學起來並複製。製程偏誤（Process Bias）出在標註與編輯：標註者的主觀或文化差異造成不一致，例如不同人對同一句話的情感判斷不同。口訣：來源＝抽到誰；內容＝資料寫了什麼；製程＝誰標、怎麼標。",
