   "summary": "「公平」不只一種，要依場景選指標。群體平等率（Demographic Parity，也稱統計均等）：各群體獲得正向預測（核准、錄取）的比例要相近，只看結果比例，不管實際有沒有資格。機會平等（Equal Opportunity）：在「真正應該被選中」的人之中，各群體被正確預測為正的機率（TPR）要相同，強調有資格的人不能被漏掉，適合醫療診斷、福利核准。均衡機率（Equalized Odds）：不只 TPR，連誤判（FPR）也要一致，最嚴格，常用於司法、信用評估，但實務上難完全達成。例：男性通過率 55%、女性 30%，兩群的正向決策比例差很多，就不符合統計均等。",
