   "guidePages": "",
   "summary": "一般交叉驗證會隨機打亂資料，但時間序列資料有先後順序、前後相關，隨機切分會讓模型「偷看到未來」（資料洩漏），分數虛高。正確做法是：驗證資料一定在訓練資料之後。滾動視窗驗證（Rolling Window）：訓練視窗長度固定，一格一格往後滑，每次訓練用的都是最近一段資料；擴張視窗（Expanding Window）則起點固定、訓練集越來越大。兩者都是「用過去訓練、用未來驗證」，反覆多折，可以檢視模型面對環境變化（概念漂移）時是否仍然穩健。固定單一時間切分只驗一次，環境改變後驗證集就過時了。",
