   "guidePages": "",
   "summary": "RAG（檢索增強生成）先從知識庫找出相關片段，再交給 LLM 依這些內容回答，可降低幻覺、使用最新或內部資料。檢索階段常見兩路：向量搜尋把文字轉成嵌入向量，找語意相近的內容，擅長同義改寫，但對專有名詞、型號、代碼、縮寫這類字面必須相符的查詢容易失準；關鍵字搜尋（BM25）按詞彙命中與稀有度評分，字面精準但不懂同義。混合搜尋（Hybrid Search）兩路同時跑，再用 RRF（倒數排名融合）合併：每份文件在各路排名 r 的得分為 1/(k＋r)，各路加總（k 常取 60）。只用名次，所以不必硬把兩種尺度不同的分數湊在一起。",
