   "summary": "傳統信用評分卡是銀行評估貸款違約風險的「可解釋」模型，核心是邏輯迴歸，並依標準化流程開發，因為監理機關要求模型可解釋、可稽核。典型流程：定義好壞客戶與準備資料 → 變數分箱（Binning），計算各箱的證據權重（WOE），用資訊值（IV）評估變數預測力 → 特徵選擇與多重共線性檢查 → 邏輯迴歸建模 → 把係數換算成分數 → 驗證（區分力如 KS、AUC；穩定性如 PSI）→ 上線後持續監控。PSI（群體穩定性指標）比較模型開發樣本與近期樣本的分佈差異，判斷模型是否因客群變動而失效。以生成式模型做特徵學習，不屬於傳統評分卡的常見步驟。",
