   "summary": "時間複雜度用 Big-O 描述「資料量 n 變大時，執行步驟數怎麼成長」，只看成長趨勢，忽略常數與低階項。常見從快到慢：O(1) 常數（直接用索引取值）、O(log n)（二分搜尋，每次砍一半）、O(n)（掃過一遍）、O(n log n)（高效排序）、O(n²)（雙層迴圈）。以兩兩配對為例：n 位客戶彼此比對，次數是 n(n−1)/2，最大的項是 n²，所以是 O(n²)。資料量乘 10，時間約乘 100。這就是為什麼大規模的全點對相似度計算，常要靠索引或近似最近鄰（ANN）加速。",
